"""Make a small client-side paginated viewer for compressed exact comment records."""
import argparse,html,json
from pathlib import Path

def main():
    p=argparse.ArgumentParser();p.add_argument('--catalog',required=True,type=Path);a=p.parse_args();m=json.loads((a.catalog/'manifest.json').read_text())
    options=''.join('<option value="'+html.escape(x['group'],quote=True)+'">'+html.escape(x['group'])+' · '+str(x['comments'])+'</option>' for x in m['groups'])
    page='''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'self'; script-src 'self'; style-src 'unsafe-inline'; connect-src 'self'; object-src 'none'; base-uri 'none'"><title>Comentarios del firmware antiguo HGW</title><style>body{font:16px system-ui;background:#101827;color:#dfeaff;max-width:1100px;margin:30px auto;padding:0 18px}input,select,button{font:inherit;padding:10px;margin:6px;background:#233751;color:inherit;border:1px solid #526984;border-radius:6px}input{width:70%}article{padding:15px;margin:14px 0;border:1px solid #39536e;border-radius:8px}h2{font-size:14px;overflow-wrap:anywhere}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px}small{overflow-wrap:anywhere;color:#a9bdd4}</style><script src="viewer.js" defer></script></head><body><h1>Comentarios del firmware antiguo</h1><p>'''+str(m['comments'])+''' comentarios · '''+str(m['raw_bytes'])+''' bytes originales. Git conserva todas las fuentes; este catálogo recoge C/C++.</p><p>La búsqueda y descompresión se ejecutan en tu navegador. Abre esta página mediante HTTPS. Para consulta offline, utiliza los documentos y JSON comprimidos por componente.</p><select id="group">'''+options+'''</select><button id="load">Cargar componente</button><input id="search" placeholder="Buscar texto, archivo o hash"><button id="previous">Anterior</button><button id="next">Siguiente</button><p id="status"></p><main id="results"></main></body></html>'''
    js=''''use strict';
let records=[],filtered=[],page=0;const size=40;const status=document.querySelector('#status');
function render(){const root=document.querySelector('#results');root.replaceChildren();for(const r of filtered.slice(page*size,(page+1)*size)){const a=document.createElement('article'),h=document.createElement('h2'),s=document.createElement('small'),p=document.createElement('pre');h.textContent=r.path+':'+r.line;s.textContent='Bytes '+r.offset+'..'+r.end_offset+' · SHA256 '+r.sha256;p.textContent=r.text;a.append(h,s,p);root.append(a);}status.textContent=filtered.length+' coincidencias · página '+(page+1)+' / '+Math.max(1,Math.ceil(filtered.length/size));}
document.querySelector('#load').addEventListener('click',async()=>{if(location.protocol!=='https:'){status.textContent='HTTPS requerido. Consulta los documentos comprimidos para lectura offline.';return;}status.textContent='Cargando y descomprimiendo en el cliente…';try{if(typeof DecompressionStream==='undefined')throw Error('Este navegador no admite DecompressionStream');const selected=document.querySelector('#group').value;const response=await fetch(selected+'/comments.jsonl.gz',{credentials:'same-origin'});if(!response.ok)throw Error('HTTP '+response.status);const text=await new Response(response.body.pipeThrough(new DecompressionStream('gzip'))).text();records=text.split('\\n').filter(Boolean).map(x=>JSON.parse(x));filtered=records;page=0;render();}catch(e){status.textContent=String(e);}});
let timer;document.querySelector('#search').addEventListener('input',e=>{clearTimeout(timer);timer=setTimeout(()=>{const q=e.target.value.toLocaleLowerCase();filtered=records.filter(r=>(r.path+' '+r.sha256+' '+r.text).toLocaleLowerCase().includes(q));page=0;render();},180);});
document.querySelector('#previous').addEventListener('click',()=>{page=Math.max(0,page-1);render();});document.querySelector('#next').addEventListener('click',()=>{page=Math.min(Math.max(0,Math.ceil(filtered.length/size)-1),page+1);render();});
'''
    (a.catalog/'index.html').write_text(page,encoding='utf-8');(a.catalog/'viewer.js').write_text(js,encoding='utf-8')
    print(json.dumps({'page_created':True,'comments':m['comments'],'client_paging':True,'https_required':True}))
if __name__=='__main__':main()
